#!/usr/bin/env python3
"""Generate executable capabilities and the parity table from one reviewed specification."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / 'core/capabilities/src/main/kotlin/dev/riffworkbench/capabilities/FeatureRegistry.kt'
MATRIX = ROOT / 'docs/PARITY.md'

def outputs():
    spec = json.loads((ROOT / 'spec/features.json').read_text())
    lines = []
    table = ['# Paritätsmatrix', '', 'Generiert aus `spec/features.json`. Jede Zeile bewertet fünf Fähigkeiten getrennt. **Lesen:** im Modell und in der nativen Datei vorhanden und aus Importen übernommen, soweit das Format es kennt. **Darstellen:** im Notensatz oder in der Oberfläche sichtbar. **Bearbeiten:** in der App über Editor-Befehle änderbar. **Playback:** in Wiedergabe und Audioexport hörbar. **Export:** in mindestens einem Austauschformat (GP7, MIDI, MusicXML, ASCII) oder Medienexport (SVG, PDF, WAV, Stems) geschrieben; native Erhaltung allein zählt nicht.', '', '`EXPERIMENTAL` heißt vorhanden, aber eingeschränkt (Grenzen in CONTRACTS.md). `NOT_APPLICABLE` heißt, die Fähigkeit ergibt für das Merkmal keinen Sinn. `SCAFFOLDED` ist nur Modell/Vertrag ohne Umsetzung.', '', '## GP-Dateitreue', '', 'GP3/4/5, GPX und GP7/8 werden gelesen, GP7 wird geschrieben. Geprüft ist das gegen selbst erzeugte Dateien und Rundreisen innerhalb der App, nicht gegen Guitar Pro Desktop; deshalb stehen diese Zeilen auf `DESKTOP_PENDING`. GP8-spezifische Inhalte (Backing Track, Sync-Punkte, Assets) landen im Verlustbericht. Native Speicherung einer Eigenschaft ist kein GP-Fidelity-Nachweis.', '', '## Prüfstand', '', '`AUTOMATED`: JVM-/Robolectric-Tests decken den beschriebenen Umfang ab. `DEVICE_PENDING`: implementiert und automatisiert geprüft, die Abnahme auf echter Hardware fehlt. `DESKTOP_PENDING`: der Gegencheck in Guitar Pro Desktop beziehungsweise Cubase fehlt. `AUTOMATED_PENDING`: implementiert, aber noch ohne eigenen Test. `CONTRACT_ONLY`: nur Vertrag.', '', '| ID | Funktion | Lesen | Darstellen | Bearbeiten | Playback | Export | Etappe | Vertrag | Prüfung |', '|---|---|---|---|---|---|---|---|---|---|']
    for f in spec['features']:
        fields = ', '.join(json.dumps(f[k], ensure_ascii=False) for k in ('id', 'labelDe', 'labelEn', 'group', 'groupDe', 'route'))
        dimensions = ', '.join(f'Dimension.{d} to ImplementationStatus.{s}' for d, s in f['dimensions'].items())
        lines.append(f'        Feature({fields}, Milestone.{f["stage"]}, {json.dumps(f["contractId"])}, mapOf({dimensions}), Verification.{f["verification"]})')
        table.append('| ' + ' | '.join([f['id'], f['labelDe'], *f['dimensions'].values(), f['stage'], f'[{f["contractId"]}](CONTRACTS.md#{f["contractId"].lower()})', f['verification']]) + ' |')
    source = '// Generated by tools/generate_registry.py from spec/features.json. Do not edit.\npackage dev.riffworkbench.capabilities\n\nobject FeatureRegistry {\n    val all: List<Feature> = listOf(\n' + ',\n'.join(lines) + '\n    )\n    fun group(id: String) = all.filter { it.group == id }\n    fun find(id: String) = all.firstOrNull { it.id == id }\n}\n'
    return {TARGET: source, MATRIX: '\n'.join(table) + '\n'}

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for path, content in outputs().items():
        if args.check:
            if not path.exists() or path.read_text() != content:
                raise SystemExit(f'Out of date: {path.relative_to(ROOT)}; run python3 tools/generate_registry.py')
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content)
